create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,username text not null unique check(username ~ '^[a-z0-9_]{3,32}$'),display_name text not null,avatar_url text);
create unique index if not exists profile_username_ci on public.profiles(lower(username));
create table if not exists public.workspaces(id uuid primary key,name text not null,timezone text not null default 'Asia/Kolkata');
insert into public.workspaces(id,name) values('00000000-0000-4000-8000-000000000001','Apix') on conflict(id) do nothing;
create table if not exists public.workspace_members(workspace_id uuid not null references public.workspaces(id),user_id uuid not null references public.profiles(id),role text not null default 'member' check(role in('admin','member')),color_hex text not null default '#7565da',primary key(workspace_id,user_id));
create or replace function public.is_member(w uuid) returns boolean language sql security definer stable set search_path='' as $$select exists(select 1 from public.workspace_members where workspace_id=w and user_id=(select auth.uid()))$$;
create or replace function public.is_admin(w uuid) returns boolean language sql security definer stable set search_path='' as $$select exists(select 1 from public.workspace_members where workspace_id=w and user_id=(select auth.uid()) and role='admin')$$;
create or replace function public.resolve_login_email(p_username text) returns text language sql stable security definer set search_path='' as $$select u.email from public.profiles p join auth.users u on p.id=u.id where lower(p.username)=lower(trim(p_username)) limit 1$$;
revoke all on function public.resolve_login_email(text) from public;
grant execute on function public.resolve_login_email(text) to anon,authenticated;
create table if not exists public.posts(
id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id),title text not null,brief text not null default '',caption text not null default '',platform text not null check(platform in ('LinkedIn','Instagram','Facebook','X','YouTube')),format text not null default 'Text',funnel text not null default 'TOFU',status text not null default 'Idea',scheduled_at timestamptz,published_at timestamptz,published_url text,primary_owner_id uuid references public.profiles(id),created_by uuid not null references public.profiles(id),pillar text not null default 'Thought Leadership',tags text[] not null default '{}',locked boolean not null default false,created_at timestamptz default now(),updated_at timestamptz default now());
create index if not exists posts_calendar on public.posts(workspace_id,scheduled_at);
create table if not exists public.ideas(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id),title text not null,description text not null default '',stack text not null default 'Unsorted',source_url text not null default '',status text not null default 'Captured',created_by uuid not null references public.profiles(id),created_at timestamptz default now());
create table if not exists public.comments(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id),post_id uuid not null references public.posts(id),author_id uuid not null references public.profiles(id),body text not null,created_at timestamptz default now());
create table if not exists public.notifications(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id),recipient_id uuid not null references public.profiles(id),post_id uuid references public.posts(id),title text not null,body text not null default '',read_at timestamptz,created_at timestamptz default now());
create table if not exists public.schedule_history(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id),post_id uuid not null references public.posts(id),old_at timestamptz,new_at timestamptz,changed_by uuid references public.profiles(id),created_at timestamptz default now());
create table if not exists public.reschedule_suggestions(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id),post_id uuid not null references public.posts(id),old_at timestamptz not null,proposed_at timestamptz not null,status text not null default 'pending',created_at timestamptz default now(),resolved_at timestamptz);
create unique index if not exists suggestions_one_pending on public.reschedule_suggestions(post_id) where status='pending';
create or replace function public.audit_schedule() returns trigger language plpgsql security definer set search_path='' as $$begin if old.scheduled_at is distinct from new.scheduled_at then insert into public.schedule_history(workspace_id,post_id,old_at,new_at,changed_by) values(new.workspace_id,new.id,old.scheduled_at,new.scheduled_at,(select auth.uid())); update public.reschedule_suggestions set status='stale',resolved_at=now() where post_id=new.id and status='pending'; end if;return new;end$$;
drop trigger if exists audit_schedule_update on public.posts;
create trigger audit_schedule_update after update of scheduled_at on public.posts for each row execute function public.audit_schedule();
create or replace function public.validate_post_members() returns trigger language plpgsql security definer set search_path='' as $$begin if not exists(select 1 from public.workspace_members where workspace_id=new.workspace_id and user_id=new.created_by) then raise exception 'Invalid creator';end if;if new.primary_owner_id is not null and not exists(select 1 from public.workspace_members where workspace_id=new.workspace_id and user_id=new.primary_owner_id) then raise exception 'Invalid owner';end if;return new;end$$;
drop trigger if exists check_post_members on public.posts;
create trigger check_post_members before insert or update on public.posts for each row execute function public.validate_post_members();
create or replace function public.validate_comment_workspace() returns trigger language plpgsql security definer set search_path='' as $$begin if not exists(select 1 from public.posts where id=new.post_id and workspace_id=new.workspace_id) then raise exception 'Workspace mismatch';end if;return new;end$$;
drop trigger if exists comments_workspace_guard on public.comments;
create trigger comments_workspace_guard before insert or update on public.comments for each row execute function public.validate_comment_workspace();
alter table public.profiles enable row level security;
alter table public.workspaces enable row level security;
alter table public.workspace_members enable row level security;
alter table public.posts enable row level security;
alter table public.ideas enable row level security;
alter table public.comments enable row level security;
alter table public.notifications enable row level security;
alter table public.schedule_history enable row level security;
alter table public.reschedule_suggestions enable row level security;
create policy "profiles read" on public.profiles for select to authenticated using(id=auth.uid() or exists(select 1 from public.workspace_members m where m.user_id=profiles.id and public.is_member(m.workspace_id)));
create policy "workspace read" on public.workspaces for select to authenticated using(public.is_member(id));
create policy "members read" on public.workspace_members for select to authenticated using(public.is_member(workspace_id));
create policy "members admin add" on public.workspace_members for insert to authenticated with check(public.is_admin(workspace_id));
create policy "posts read" on public.posts for select to authenticated using(public.is_member(workspace_id));
create policy "posts create" on public.posts for insert to authenticated with check(public.is_member(workspace_id) and created_by=auth.uid());
create policy "posts edit" on public.posts for update to authenticated using(public.is_member(workspace_id)) with check(public.is_member(workspace_id));
create policy "ideas read" on public.ideas for select to authenticated using(public.is_member(workspace_id));
create policy "ideas add" on public.ideas for insert to authenticated with check(public.is_member(workspace_id) and created_by=auth.uid());
create policy "ideas edit" on public.ideas for update to authenticated using(public.is_member(workspace_id)) with check(public.is_member(workspace_id));
create policy "comments read" on public.comments for select to authenticated using(public.is_member(workspace_id));
create policy "comments add" on public.comments for insert to authenticated with check(public.is_member(workspace_id) and author_id=auth.uid());
create policy "notifications read" on public.notifications for select to authenticated using(recipient_id=auth.uid() and public.is_member(workspace_id));
create policy "notifications add" on public.notifications for insert to authenticated with check(public.is_member(workspace_id) and exists(select 1 from public.workspace_members m where m.workspace_id=notifications.workspace_id and m.user_id=notifications.recipient_id));
create policy "notifications update" on public.notifications for update to authenticated using(recipient_id=auth.uid()) with check(recipient_id=auth.uid());
create policy "history read" on public.schedule_history for select to authenticated using(public.is_member(workspace_id));
create policy "suggestions read" on public.reschedule_suggestions for select to authenticated using(public.is_member(workspace_id));
